function animate(time=0){raf=requestAnimationFrame(animate);const dt=Math.min((time-lastTime)/1000,.1);lastTime=time;updateAmbient(dt);theme?.update?.(dt);city.rail?.update(city.ambient.time*1.7);city.vehicles?.update(city.ambient.time*1.65);if(city.placement){city.people.placement=city.placement;city.vehicles.placement=city.placement;}city.people?.update(city.ambient.time);city.outskirts?.update(city.ambient.time);if(fly){const angle=city.ambient.time*.07;city.camera.position.set(Math.cos(angle)*32,22+Math.sin(angle*.7)*3,Math.sin(angle)*32);city.controls.target.lerp(new THREE.Vector3(0,0,0),.03);}if(focusAnim){focusAnim.t=Math.min(1,focusAnim.t+dt*1.2);const t=1-Math.pow(1-focusAnim.t,3);city.camera.position.lerpVectors(focusAnim.start,focusAnim.end,t);city.controls.target.lerpVectors(focusAnim.targetStart,focusAnim.targetEnd,t);if(focusAnim.t===1)focusAnim=null;}if(city.walk?.active)city.walk.update(dt);else city.controls.update();if(city.scene.fog){const distance=city.camera.position.distanceTo(city.controls.target),extra=Math.max(0,distance-55)*.75;city.scene.fog.near=100+extra;city.scene.fog.far=220+extra;}const bearing=city.controls.getAzimuthalAngle();document.querySelector('.north-arrow').style.transform=`rotate(${-bearing*180/Math.PI}deg)`;document.querySelector('#compass').setAttribute('aria-label',`Face north. Current bearing ${Math.round(((bearing*180/Math.PI)%360+360)%360)} degrees`);dimProjectContext();city.renderer.render(city.scene,city.camera);if(focusedProject){const p=focusedProject.position;vector.set(p[0],1.1,p[1]).project(city.camera);focusOpen.style.left=`${THREE.MathUtils.clamp((vector.x*.5+.5)*city.el.clientWidth,85,city.el.clientWidth-85)}px`;focusOpen.style.top=`${THREE.MathUtils.clamp((-vector.y*.5+.5)*city.el.clientHeight,120,city.el.clientHeight-125)}px`;}for(const {p,g} of city.buildings){vector.set(g.position.x,3.5,g.position.z).project(city.camera);const el=document.querySelector(`[data-project="${p.id}"]`);if(!el)continue;el.style.display=g.visible&&vector.z<1&&(!focusedProject||focusedProject.id===p.id)?'block':'none';el.style.left=`${(vector.x*.5+.5)*city.el.clientWidth}px`;el.style.top=`${(-vector.y*.5+.5)*city.el.clientHeight+(p.id==='uploaded-architecture'?35:0)}px`;}if(viewer){viewer.controls.update();viewer.renderer.render(viewer.scene,viewer.camera);}}
function stopFly(){fly=false;document.querySelector('#fly').classList.remove('active');document.querySelector('#fly').setAttribute('aria-pressed','false');}
let focusedProject=null;const dimmedObjects=new Map();
const focusOpen=document.createElement('button');focusOpen.id='focus-open';focusOpen.className='focus-open';focusOpen.textContent='Open project';focusOpen.hidden=true;document.querySelector('.scene-wrap').append(focusOpen);focusOpen.onclick=()=>{const p=focusedProject;if(p)openProject(p);};
