function clearProjectFocus(){focusedProject=null;if(city)city.controls.minDistance=15;for(const [o,old]of dimmedObjects){const current=Array.isArray(o.material)?o.material:[o.material];o.material=old;current.forEach(m=>m.dispose());}dimmedObjects.clear();focusOpen.hidden=focusClose.hidden=true;document.querySelectorAll('[data-open]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});}
function dimProjectContext(){if(!focusedProject)return;city.scene.traverse(o=>{if(!o.isMesh||dimmedObjects.has(o))return;let a=o;while(a){if(a.userData.projectId===focusedProject.id)return;a=a.parent;}const old=o.material;const dim=m=>{const c=m.clone();c.transparent=true;c.opacity=.16;c.depthWrite=false;c.color?.multiplyScalar(.45);c.emissive?.multiplyScalar(.2);return c;};dimmedObjects.set(o,old);o.material=Array.isArray(old)?old.map(dim):dim(old);});}
function selectProject(p){if(!p?.position)return;clearProjectFocus();focusedProject=p;city.controls.minDistance=5;focusProject(p);dimProjectContext();focusOpen.hidden=focusClose.hidden=false;focusOpen.setAttribute('aria-label',`Open ${p.name}`);document.querySelectorAll('[data-open]').forEach(b=>{const on=b.dataset.open===p.id;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});}
function focusProject(p){if(!city)return;city.walk?.stop();stopFly();const building=city.buildings.find(b=>b.p.id===p.id),angle=building?.g.userData.frontage?.angle||0,front=new THREE.Vector3(Math.sin(angle),0,Math.cos(angle)),target=new THREE.Vector3(p.position[0],.45,p.position[1]),offset=front.multiplyScalar(8).add(new THREE.Vector3(0,4.5,0));focusAnim={start:city.camera.position.clone(),end:target.clone().add(offset),targetStart:city.controls.target.clone(),targetEnd:target,t:reduced?1:0};if(reduced){city.camera.position.copy(focusAnim.end);city.controls.target.copy(target);focusAnim=null;}}

function cleanupViewer(){modelToken++;if(!viewer)return;viewer.controls.dispose();viewer.ro.disconnect();disposeObject(viewer.scene);viewer.renderer.dispose();viewer.renderer.domElement.remove();viewer=null;document.querySelector('#model-view').querySelectorAll('.error,.model-status').forEach(e=>e.remove());}
async function viewModel(file,p){cleanupViewer();const token=++modelToken;viewer=setup(document.querySelector('#model-view'),true);viewer.night=viewerNight;if(!p.local){viewer.camera.position.set(0,3.1,8);viewer.controls.target.set(0,.65,0);viewer.controls.update();}if(!file){viewer.scene.add(p.local?placeholder(p):projectModel(p));if(!p.local)viewer.scene.children.at(-1).scale.y=.65;theme?.applyViewer(viewerNight);return;}const label=document.createElement('div');label.className='model-status';label.textContent=p.local?'Loading your local model...':'Loading bundled sample model...';document.querySelector('#model-view').append(label);try{const model=normalizeModel(await loadGLB(file),3,1.8);if(token!==modelToken){disposeObject(model);return;}viewer.scene.add(p.premium?stageVilla(model):model);theme?.applyViewer(viewerNight);label.textContent=p.local?'Local GLB · orbit view':'Bundled sample GLB · orbit view';}catch(e){if(token!==modelToken)return;viewer.scene.add(placeholder(p));theme?.applyViewer(viewerNight);label.textContent='Model unavailable. Showing temporary placeholder.';}}
function photosMarkup(files){return files?.length?`<div class="local-gallery">${files.map((f,i)=>`<img src="${typeof f==='string'?f:blobURL(f)}" alt="${typeof f==='string'?'Exact-model render':'Uploaded project photo'} ${i+1}" loading="lazy">`).join('')}</div>`:'<div class="photo-empty">No photographs uploaded yet.</div>';}
function openProject(p){if(typeof p==='string')p=allProjects().find(q=>q.id===p);if(!p||!p.position)return;clearProjectFocus();const mapBuilding=city.buildings.find(b=>b.p.id===p.id);if(mapBuilding?.g.userData.modelState==='error'){mapBuilding.g.userData.modelState='loading';mapBuilding.g.userData.retryModel?.();}city.walk?.stop();selection=p;viewerNight=!!theme?.night;updateViewerToggle();focusProject(p);cleanupViewer();for(const url of objectURLs)URL.revokeObjectURL(url);objectURLs.clear();const local=!!p.local;const demoRooms=p.id==='courtyard'?['Living room','Bedroom','Kitchen']:[];document.querySelector('#details').innerHTML=`<div class="board-number">${String(allProjects().indexOf(p)+1).padStart(2,'0')}</div><span class="demo-badge">${local?'DEVICE-LOCAL UPLOAD':'ILLUSTRATIVE DEMO / '+String(allProjects().indexOf(p)+1).padStart(2,'0')}</span><h2 id="project-title">${escape(p.name)}</h2>${local&&!p.model?'<p class="placeholder-note">Temporary placeholder. This building is not your project design; upload a GLB to replace it.</p>':''}<p>${escape(p.description||'No description provided.')}</p><div class="facts"><div><span>Plot type</span><strong>${escape(p.type)}</strong></div><div><span>Model</span><strong>${local?(p.model?'Uploaded GLB':'Temporary placeholder'):(p.model?'Bundled sample GLB':'Procedural demo')}</strong></div><div><span>Location</span><strong>${escape(p.location||'Not supplied')}</strong></div><div><span>Year</span><strong>${escape(p.year||'Not supplied')}</strong></div></div>${p.source?`<p><a href="${p.source}" target="_blank" rel="noopener noreferrer">Model source: ${escape(p.sourceLabel||(p.premium?'Innerscene / CC0':'CGTrader / ArchNovaStudio'))}</a></p>`:''}<div id="detail-photos">${photosMarkup(p.photos)}</div>${local&&p.rooms?.length?`<h3>Interiors / rooms</h3><div class="room-tabs"><button class="chip active" data-room="exterior">Exterior</button>${p.rooms.map((r,i)=>`<button class="chip" data-room="${i}">${escape(r.name)}</button>`).join('')}</div><p id="room-status">Exterior view</p>`:''}${demoRooms.length?`<h3>Furnished interior study</h3><p>Original procedural rooms, illustrative only. Not a verified interior of this exterior model.</p><div class="room-tabs"><button class="chip" data-demo-room="Exterior">Exterior</button>${demoRooms.map(n=>`<button class="chip" data-demo-room="${n}">${n}</button>`).join('')}</div>`:''}<p>Orbit and room switching only. Continuous interior walkthrough is not available in this demo.</p>${local?'<p class="local-warning">Uploaded files are visible only in this browser on this device. They are not shared or backed up.</p>':''}`;dialog.showModal();viewModel(p.model||null,p);document.querySelectorAll('[data-demo-room]').forEach(b=>b.onclick=()=>{if(b.dataset.demoRoom==='Exterior'){dialog.scrollTop=0;return viewModel(p.model||null,p);}dialog.scrollTop=0;cleanupViewer();viewer=setup(document.querySelector('#model-view'),true);viewer.night=viewerNight;viewer.scene.add(interiorRoom(b.dataset.demoRoom));viewer.controls.target.set(0,.2,0);viewer.controls.minDistance=.7;viewer.camera.position.set(1.3,1.1,1.4);viewer.controls.update();theme?.applyViewer(viewerNight);});document.querySelectorAll('[data-room]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-room]').forEach(b=>b.classList.toggle('active',b===button));const r=button.dataset.room==='exterior'?null:p.rooms[Number(button.dataset.room)];document.querySelector('#detail-photos').innerHTML=photosMarkup(r?r.photos:p.photos);document.querySelector('#room-status').textContent=r?(r.model?`${r.name}: uploaded room model, orbit view`:`${r.name}: photos only, no 3D model uploaded`):'Exterior view';if(r&&!r.model){cleanupViewer();document.querySelector('#model-view').insertAdjacentHTML('beforeend','<p class="model-status">This room has photos only. No room geometry has been invented.</p>');}else viewModel(r?r.model:p.model,p);});}
const viewerToggle=document.createElement('button');viewerToggle.id='viewer-theme';viewerToggle.className='tool';dialog.querySelector('.modal-head').insertBefore(viewerToggle,dialog.querySelector('.close'));function updateViewerToggle(){viewerToggle.textContent=viewerNight?'Day view':'Night view';viewerToggle.setAttribute('aria-label',viewerNight?'Switch project to day view':'Switch project to night view');viewerToggle.setAttribute('aria-pressed',String(viewerNight));dialog.classList.toggle('viewer-night',viewerNight);}viewerToggle.onclick=()=>{viewerNight=!viewerNight;if(viewer)viewer.night=viewerNight;updateViewerToggle();theme?.applyViewer(viewerNight);};
dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{cleanupViewer();selection=null;});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function renderList(){const list=allProjects().filter(p=>currentFilter==='all'||p.type===currentFilter);document.querySelector('#count').textContent=String(list.length).padStart(2,'0');document.querySelector('#project-list').innerHTML=list.length?list.map(p=>`<button class="project" data-open="${p.id}"><span class="num">${String(allProjects().indexOf(p)+1).padStart(2,'0')}</span><span><strong>${escape(p.name)}</strong><small>${escape(p.type)} / ${p.local?'local upload':'illustrative demo'}</small></span><span class="arrow">↗</span></button>`).join(''):'<div class="empty-list">No projects on this plot type yet.</div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>selectProject(allProjects().find(p=>p.id===b.dataset.open)));}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{clearProjectFocus();currentFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(c=>{const on=c===b;c.classList.toggle('active',on);c.setAttribute('aria-pressed',String(on));});renderList();if(city)city.buildings.forEach(({p,g})=>{g.visible=currentFilter==='all'||p.type===currentFilter;});theme?.apply();});
document.querySelector('#zoom-in').onclick=()=>{if(city){city.walk?.stop();stopFly();city.camera.position.sub(city.controls.target).multiplyScalar(.83).add(city.controls.target);}};document.querySelector('#zoom-out').onclick=()=>{if(city){city.walk?.stop();stopFly();city.camera.position.sub(city.controls.target).multiplyScalar(1.2).add(city.controls.target);}};document.querySelector('#reset').onclick=()=>{clearProjectFocus();if(city){city.walk?.stop();stopFly();focusAnim=null;city.camera.position.set(74,88,84);city.controls.target.set(0,0,0);}};document.querySelector('#fly').setAttribute('aria-pressed','false');document.querySelector('#fly').onclick=()=>{if(city){city.walk?.stop();fly=!fly;focusAnim=null;document.querySelector('#fly').classList.toggle('active',fly);document.querySelector('#fly').setAttribute('aria-pressed',String(fly));}};
const speedControl=document.createElement('button');speedControl.id='city-speed';speedControl.className='tool';speedControl.textContent='1×';speedControl.title='City motion speed';speedControl.setAttribute('aria-label','City speed 1 times. Click to increase');document.querySelector('.tools').append(speedControl);speedControl.onclick=()=>{const speeds=[1,2,4,.5],current=city.ambient.speed||1,next=speeds[(speeds.indexOf(current)+1)%speeds.length];city.ambient.speed=next;speedControl.textContent=next+'×';speedControl.setAttribute('aria-label','City speed '+next+' times. Click to change')};document.querySelector('#motion').setAttribute('aria-pressed',String(!reduced));document.querySelector('#motion').onclick=()=>{if(city?.ambient){city.ambient.enabled=!city.ambient.enabled;document.querySelector('#motion').setAttribute('aria-pressed',String(city.ambient.enabled));document.querySelector('#motion').classList.toggle('active',city.ambient.enabled);}};
document.querySelector('#compass').onclick=()=>{if(!city)return;city.walk?.stop();stopFly();const target=city.controls.target.clone(),offset=city.camera.position.clone().sub(target),horizontal=Math.hypot(offset.x,offset.z);const end=target.clone().add(new THREE.Vector3(0,offset.y,horizontal));if(reduced){city.camera.position.copy(end);city.controls.update();focusAnim=null;}else focusAnim={start:city.camera.position.clone(),end,targetStart:target.clone(),targetEnd:target,t:0};};
function notice(title,body){const d=document.querySelector('#notice-dialog');document.querySelector('#notice-content').innerHTML=`<span class="eyebrow">FXARCH / Phase 1</span><h2 id="notice-title">${title}</h2>${body}<button class="tool notice-close">Close</button>`;d.setAttribute('aria-labelledby','notice-title');d.showModal();d.querySelector('button').onclick=()=>d.close();}
document.querySelector('#about').onclick=()=>notice('Architecture in context.','<p>A monochrome city provides the setting. Colored buildings reveal individual projects, each tied to a roadside, corner or center-block plot.</p><p>This prototype has three procedural demos and one licensed, staged villa sample, all explicitly labeled. No actual portfolio, firm location, project dates or photographs have been invented.</p><p>Next: approved project models, photos and metadata; secure admin uploads; automatic matching-plot placement.</p>');document.querySelector('#admin').onclick=()=>adminPanel?.open();renderList();try{generateCity();}catch(error){console.error(error);cityEl.innerHTML='<div class="error">This interactive city needs WebGL. Try an up-to-date Chrome, Safari or Firefox with hardware acceleration enabled. Project names remain available below.</div>';}

async function syncLocal(){clearProjectFocus();
 const records=await storage.list();localRecords=records;
 if(!city)return;
 for(const b of city.buildings.filter(b=>b.p.local)){city.scene.remove(b.g);disposeObject(b.g);document.querySelector(`[data-project="${b.p.id}"]`)?.remove();}
 city.buildings=city.buildings.filter(b=>!b.p.local);city.plots.forEach(plot=>plot.occupied=city.buildings.some(b=>Math.abs(b.g.position.x-plot.x)<.01&&Math.abs(b.g.position.z-plot.z)<.01));
 city.contextGroups.forEach(g=>g.visible=true);
 for(const p of records){let plot=city.plots.find(q=>q.id===p.plotId);if(!plot||plot.occupied||plot.reserved){plot=city.plots.find(q=>q.type===p.type&&!q.occupied&&!q.reserved);if(!plot)continue;p.plotId=plot.id;await storage.save(p);} plot.occupied=true;city.contextGroups.get(plot.id)?.visible&&(city.contextGroups.get(plot.id).visible=false);p.position=[plot.x,plot.z];const g=new THREE.Group();g.userData.projectId=p.id;g.position.set(plot.x,0,plot.z);const temp=placeholder(p);temp.scale.setScalar(Math.min(1,plot.width*.7/2.3,plot.depth*.7/2.3));g.add(temp);city.scene.add(g);g.visible=currentFilter==='all'||p.type===currentFilter;city.buildings.push({p,g});const label=document.createElement('div');label.className='label';label.textContent=`${p.name} / ${p.model?'local model':'temporary placeholder'}`;label.dataset.project=p.id;document.querySelector('#labels').append(label);
 if(p.model)loadGLB(p.model).then(model=>{if(!g.parent){disposeObject(model);return;}g.remove(temp);disposeObject(temp);const footprint=city.plots.find(q=>q.id===p.plotId);g.add(normalizeModel(model,Math.min(3.4,(footprint?.width||5)*.65,(footprint?.depth||5)*.65),p.type==='center-block'?2.4:1.8));if(theme?.night)theme.apply();if(city.placement)city.placement=installPlacement(city);if(city.collision)city.collision=installCollision(city);}).catch(()=>label.textContent=`${p.name} / model failed, placeholder`);
 }
 renderList();if(theme?.night)theme.apply();city.collision=installCollision(city);
}
theme=installTheme({getCity:()=>city,getViewer:()=>viewer});
adminPanel=installAdmin({getPlots:()=>city?.plots||[],getRecords:()=>localRecords,onChanged:syncLocal});syncLocal().catch(e=>{document.querySelector('.prototype').textContent+=' Local storage is unavailable; uploads cannot be saved in this browser.';console.error('Local storage unavailable',e);});

